from format_lecon import Lesson,paras,steps,table
from diagnostics import comparison
from medicaments import antalgie
l=Lesson('Raideur et douleur cervicales')
l.add('La {cervicalgie} désigne une douleur de la région du cou, parfois irradiée vers la tête, l’épaule ou le bras. La raideur décrit une limitation ressentie ou constatée des mouvements. Ces symptômes ne désignent ni une cause unique ni automatiquement une affection bénigne.',paras('Distinguer douleur axiale, douleur radiculaire du membre supérieur, syndrome médullaire et irritation méningée. Un torticolis est une attitude anormale du cou, non un diagnostic étiologique suffisant.', 'L’absence de douleur intense ne protège pas d’une myélopathie. Inversement, une douleur très importante peut survenir sans lésion structurelle grave ; son contexte, son évolution et les signes associés guident le tri.'),(1,3,7,10))
l.add('Le {contexte modifie fortement les hypothèses}. Les cervicalgies communes sont usuelles, mais traumatisme, fièvre, déficit neurologique ou douleur brutale imposent une autre démarche. L’âge, les antécédents et le retentissement fonctionnel comptent.',paras('Les dix diagnostics forment une sélection pédagogique ordonnée, sans classement chiffré suisse de fréquence. Elle comprend des causes usuelles, des urgences et deux causes de raideur cervicale haute. Les catégories peuvent coexister.', 'Elle ne remplace pas la recherche d’une tumeur ou métastase, d’une infection profonde du cou, d’une spondyloarthrite, d’une douleur projetée cardiaque ou pulmonaire, ni d’une dystonie. Chez l’enfant, un torticolis fébrile, une difficulté à avaler, une salivation anormale ou une gêne respiratoire nécessitent une évaluation adaptée et rapide.'),(1,4,6,7,8))
an=l.subwindow('anatomie','Racine, moelle, méninges et jonction cervicale',paras('Une racine nerveuse relie un territoire sensitif et moteur au système nerveux central. Une lésion radiculaire peut donner douleur du bras, paresthésies, faiblesse et diminution d’un réflexe dans une distribution concordante.', 'La moelle cervicale contient aussi les voies destinées aux jambes : une atteinte du cou peut donc altérer la marche et les réflexes des membres inférieurs. Des signes radiculaires au niveau lésé et médullaires en dessous peuvent coexister.', 'L’irritation méningée par infection ou sang peut produire une raideur nucale. Ce mécanisme diffère de la limitation douloureuse musculosquelettique ; aucun geste clinique isolé ne suffit à exclure une urgence.', 'L’articulation entre atlas et axis assure une part importante de la rotation. Des dépôts microcristallins autour de la dent de l’axis peuvent provoquer une inflammation aiguë ; dans la polyarthrite rhumatoïde, l’atteinte ligamentaire et le pannus peuvent créer une instabilité.'),(1,3,5,8,10))
l.add('Les {bases anatomiques} expliquent les présentations différentes. Une racine atteinte donne surtout un syndrome du bras, tandis que la moelle peut affecter mains et marche. Une raideur méningée ou une instabilité cervicale haute exige une démarche spécifique.',paras(an),(1,3,5,8,10))
l.add('Le {tri recherche d’abord les urgences}. Déficit récent, trouble de marche aigu, céphalée brutale, syndrome infectieux sévère ou traumatisme à risque interdisent de conclure à une simple contracture. La prise en charge commence par la stabilité respiratoire et circulatoire.',table(['🚩 Présentation','Décision initiale'],[['Traumatisme, suspicion d’instabilité, déficit.','Protéger le rachis sans mobilisation forcée ; filière traumatologique.'],['Fièvre, céphalée, altération de conscience ou purpura.','Urgence hospitalière pour méningite/sepsis ; ne pas attendre le tableau complet.'],['Céphalée maximale brutalement, avec ou sans raideur.','Bilan urgent d’hémorragie et autres causes vasculaires.'],['Douleur inhabituelle avec Horner, trouble visuel ou déficit focal.','Rechercher dissection et ischémie ; imagerie vasculaire urgente.'],['Mains maladroites, marche perturbée, faiblesse progressive ou troubles sphinctériens.','Rechercher souffrance médullaire ; urgence si apparition ou aggravation aiguë.'],['Cancer, immunosuppression, infection récente ou douleur progressive persistante.','Bilan rapide ciblé ; urgence selon état général et signes neurologiques.']]),(1,4,5,7,8,10,13))
l.add('L’{anamnèse précise début, évolution et signes associés}. Demander traumatisme, caractère brutal ou progressif, irradiation et retentissement. Rechercher fièvre, céphalée, faiblesse, maladresse, troubles de marche et symptômes sphinctériens.',paras('Noter antécédents de cancer, infection, chirurgie rachidienne, immunosuppression, polyarthrite et rachis ankylosé. Une chute apparemment banale sur un rachis ankylosé peut provoquer une fracture.', 'Préciser médicaments, anticoagulants, consommation d’antalgiques et manipulation récente du cou. Le lien temporel avec un effort n’établit pas une cause musculaire. Sommeil, peur du mouvement, contraintes professionnelles et humeur aident à adapter les soins sans invalider la plainte ni remplacer le tri organique.'),(1,4,7,9,13))
l.add('L’{examen est général, cervical et neurologique}. Il comprend constantes, état de conscience, peau et examen des quatre membres selon le contexte. La mobilité n’est testée que si la situation le permet.',paras('Observer posture, masses et peau ; palper prudemment rachis et muscles. Examiner force, sensibilité, réflexes, dextérité et marche si possible sans risque. Rechercher signes pyramidaux et atteinte des nerfs crâniens ; compléter par épaules, gorge ou appareil cardiovasculaire selon les symptômes.', 'Une suspicion de fracture, d’instabilité inflammatoire ou de dissection exclut les mouvements forcés et les tests provocateurs de routine. Un examen neurologique initial normal n’exclut pas une urgence vasculaire débutante. Un syndrome de Horner associe notamment petite pupille et chute de paupière du même côté.'),(1,3,7,8,10,13))
l.add('Le {tableau différentiel} relie contexte, signes et décision. Le rang ne constitue pas une prévalence suisse mesurée. Les signes de gravité priment sur le caractère habituel d’une cause.',comparison(),(1,3,4,5,7,8,10,13))
l.add('Le {diagnostic positif est clinico-contextuel}. Une cervicalgie commune suppose l’absence d’argument pour une cause spécifique après évaluation. Une image dégénérative ne suffit pas à attribuer les symptômes à l’arthrose.',paras('Une radiculopathie doit être distinguée d’une douleur projetée de l’épaule ou d’une neuropathie périphérique. Une myélopathie associe signes cliniques compatibles et atteinte cervicale concordante à l’IRM ; une sténose asymptomatique n’est pas équivalente.', 'Fièvre et raideur peuvent venir d’une infection ou d’une inflammation microcristalline. Le diagnostic de dent couronnée nécessite une concordance clinique et radiologique et ne doit pas servir à écarter une infection par simple découverte de calcifications.'),(1,3,4,7,8,10))
l.add('Les {examens répondent à la question clinique}. Sans alarme, une cervicalgie commune récente ne demande pas systématiquement d’imagerie. L’urgence, la modalité et les examens biologiques changent avec l’hypothèse.',table(['Situation','Examen et portée'],[['Douleur commune récente, sans alarme.','Évaluation clinique ; réexaminer si persistance ou aggravation. Discuter imagerie après quatre à six semaines selon retentissement et évolution.'],['Traumatisme à risque chez l’adulte.','Scanner cervical selon évaluation et règles validées dans leur population ; IRM si atteinte médullaire ou ligamentaire suspectée.'],['Myélopathie, infection, tumeur ou inflammation spécifique suspectée.','IRM ciblée ; biologie et prélèvements selon cause.'],['Dissection suspectée.','Angio-IRM ou angioscanner selon disponibilité et filière ; un scanner osseux seul ne suffit pas.'],['Méningite suspectée.','Hémocultures et ponction lombaire si sûre ; imagerie préalable uniquement si indication, sans retarder les antibiotiques nécessaires.'],['Céphalée brutale suspecte.','Scanner cérébral urgent ; suites du bilan selon délai, qualité de lecture et suspicion persistante.']]),(4,5,7,8,9,10,13))
l.add('L’{algorithme} commence par l’urgence et se poursuit par la localisation du syndrome. La réévaluation fait partie du diagnostic. L’amélioration sous antalgique n’est pas un test d’exclusion des causes graves.',steps('Évaluer fonctions vitales, traumatisme, infection sévère, syndrome vasculaire et déficit neurologique.', 'Protéger le rachis si instabilité possible ; adresser immédiatement si urgence, avec appel au 144 hors hôpital si nécessaire.', 'Distinguer douleur axiale, atteinte radiculaire, médullaire, méningée et cause extracervicale.', 'Prescrire seulement les examens qui répondent à l’hypothèse et à son urgence.', 'Si cervicalgie commune retenue, proposer prise en charge active et suivi ; rouvrir le diagnostic devant évolution défavorable.'),(1,4,5,7,8,9,13))
med=antalgie(l)
l.add('La {prise en charge suisse traite le mécanisme identifié}. Dans la cervicalgie commune, expliquer, maintenir une activité adaptée et proposer des exercices progressifs. Les antalgiques sont un soutien limité ; ils ne corrigent pas une compression ni une infection.',paras('Éviter repos prolongé et collier de routine dans la cervicalgie commune ; cette règle ne s’applique pas à un rachis potentiellement instable. Une chaleur locale prudente peut aider. La physiothérapie accompagne la récupération et les objectifs fonctionnels.',med,'Une suspicion de myélopathie nécessite un avis spécialisé : une chirurgie est habituellement recommandée pour les formes modérées ou sévères, tandis que les formes légères stables font discuter intervention ou suivi structuré. Une aggravation impose une réévaluation rapide. Ne pas appliquer un délai fixe de traitement conservateur à un déficit progressif.', 'Méningite, infection rachidienne, fracture et urgence vasculaire suivent leurs filières hospitalières. Les schémas antimicrobiens, antithrombotiques ou opératoires dépendent du diagnostic confirmé et du terrain ; aucune dose étrangère n’est transposée ici.'),(1,2,4,5,7,8,9,10,11,12,13))
l.add('La {prévention et le suivi} visent fonction, sécurité et retour aux activités. Donner des critères précis de reconsultation. Adapter le traitement à l’évolution plutôt que répéter indéfiniment les prescriptions.',paras('Consulter en urgence devant fièvre avec céphalée ou altération générale, céphalée brutale, nouveau déficit, marche anormale, trouble sphinctérien ou difficulté respiratoire. Réévaluer plus tôt une douleur qui s’aggrave ou ne suit pas l’évolution attendue.', 'Dans la forme commune, encourager activité régulière, progression réaliste et gestion des facteurs qui entretiennent la gêne. Aucune posture unique ni oreiller ne garantit l’absence de récidive. Chez les patients fragiles, prévenir chutes et revoir les médicaments ; éviter de banaliser un traumatisme cervical.'),(1,2,7,8,9,10))
l.add('Le {point clé} est de qualifier le syndrome avant de traiter la douleur. Une image d’arthrose, une contracture ou une réponse antalgique ne ferment pas le diagnostic. Mains, marche, fièvre, céphalée et contexte traumatique doivent rester présents dans le raisonnement.',paras('Le conseil de bouger concerne une cervicalgie commune évaluée, pas une suspicion de fracture ou d’instabilité. Une atteinte médullaire peut se manifester davantage par la fonction des mains et des jambes que par l’intensité de la douleur du cou.'),(1,3,7,9,10))
l.quiz([
('Une arthrose visible prouve-t-elle la cause de la douleur ?','Non, la concordance clinique est nécessaire.'),
('Qu’évoquent des mains maladroites et une marche perturbée ?','Une possible myélopathie cervicale, à évaluer rapidement.'),
('Une douleur irradiant dans le bras signifie-t-elle toujours radiculopathie ?','Non, rechercher signes concordants et autres causes, notamment épaule ou nerf périphérique.'),
('Peut-on forcer la rotation après traumatisme à risque ?','Non, protéger le rachis et suivre la filière adaptée.'),
('Un traumatisme mineur sur rachis ankylosé est-il rassurant ?','Non, le risque de fracture reste important.'),
('La méningite exige-t-elle tous les signes classiques ?','Non, une présentation incomplète reste possible.'),
('Faut-il toujours un scanner avant la ponction lombaire ?','Non ; l’indication dépend du risque, et les antibiotiques urgents ne doivent pas être retardés.'),
('Une céphalée brutale améliorée par antalgique peut-elle être une hémorragie ?','Oui, le soulagement ne l’exclut pas.'),
('Douleur cervicale inhabituelle et Horner : quelle hypothèse urgente ?','Une dissection artérielle cervicale.'),
('Toute cervicalgie commune récente nécessite-t-elle une imagerie ?','Non, en l’absence d’alarme.'),
('Le collier est-il le traitement de routine de la cervicalgie commune ?','Non, favoriser l’activité adaptée après évaluation.'),
('Une calcification péri-odontoïdienne exclut-elle une infection ?','Non, elle doit être interprétée avec la clinique.'),
('Une myélopathie progressive peut-elle attendre des mois de physiothérapie ?','Non, elle impose une réévaluation spécialisée rapide.'),
('Les plafonds AIPS sont-ils des doses cibles pour tous ?','Non, indication, âge, poids, organes et interactions déterminent l’utilisation sûre.')
],(1,3,4,5,7,8,9,10,11,12,13))
l.write()
